INSERT INTO _migration_491_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igbio_movement_s2_001', 'topic_igcse_bio_cell_transport', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Diffusion is the net movement of particles from a region of…', 'multiple_choice', NULL, '["A. lower concentration to a region of higher concentration","B. high temperature to a region of low temperature","C. higher concentration to a region of lower concentration","D. high pressure to a region of low pressure"]', 'C', 'Diffusion is the net movement of particles down their concentration gradient, from a region of higher concentration to a region of lower concentration, as a result of their random motion. Movement from low to high concentration is active transport, and temperature or pressure differences are not part of the definition of diffusion. Therefore the correct answer is C: higher concentration to a region of lower concentration.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_movement_s2_002', 'topic_igcse_bio_cell_transport', 'subj_igcse_biology', 'igcse', NULL, NULL, 'By which process does water move into a root hair cell from the soil?', 'multiple_choice', NULL, '["A. Active transport","B. Transpiration","C. Diffusion of mineral ions","D. Osmosis"]', 'D', 'The soil water has a higher water potential than the cell sap, so water moves across the partially permeable cell membrane into the root hair cell by osmosis. Active transport moves mineral ions rather than water, transpiration is the loss of water vapour from leaves, and the diffusion of mineral ions does not describe the movement of water. Therefore the correct answer is D: Osmosis.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_movement_s2_003', 'topic_igcse_bio_cell_transport', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Active transport moves particles…', 'multiple_choice', NULL, '["A. against their concentration gradient, using energy from respiration","B. down their concentration gradient without using energy","C. only when the concentrations are equal on both sides","D. only across fully permeable membranes"]', 'A', 'Active transport moves particles from a region of lower concentration to a region of higher concentration, against the gradient, using energy released by respiration and carrier proteins in the membrane. Movement down the gradient without energy is diffusion, equal concentrations give no net useful transport, and fully permeable membranes cannot control which particles move. Therefore the correct answer is A: against their concentration gradient, using energy from respiration.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_movement_s2_004', 'topic_igcse_bio_cell_transport', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which gas diffuses out of a leaf during the day when photosynthesis is faster than respiration?', 'multiple_choice', NULL, '["A. Carbon dioxide","B. Oxygen","C. Nitrogen","D. Glucose"]', 'B', 'In bright light photosynthesis produces more oxygen than respiration uses, so the excess oxygen diffuses out of the leaf down its concentration gradient. Carbon dioxide diffuses into the leaf as a raw material for photosynthesis, nitrogen is not exchanged by the leaf, and glucose is a dissolved sugar, not a gas. Therefore the correct answer is B: Oxygen.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igbio_movement_s2_005', 'topic_igcse_bio_cell_transport', 'subj_igcse_biology', 'igcse', NULL, NULL, 'A bag made of partially permeable membrane containing a concentrated sugar solution is weighed, then placed in pure water for 30 minutes. What happens to the mass of the bag, and why?', 'multiple_choice', NULL, '["A. It decreases because sugar leaves the bag by osmosis","B. It stays the same because water cannot cross the membrane","C. It increases because water enters the bag by osmosis","D. It decreases because water leaves the bag by diffusion"]', 'C', 'The pure water outside the bag has a higher water potential than the sugar solution inside, so water moves into the bag across the partially permeable membrane by osmosis and the mass rises. Sugar molecules are too large to cross the membrane, water crosses the membrane readily, and osmosis drives water into the more concentrated solution, not out of it. Therefore the correct answer is C: It increases because water enters the bag by osmosis.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igbio_movement_s2_006', 'topic_igcse_bio_cell_transport', 'subj_igcse_biology', 'igcse', NULL, NULL, 'The concentration of nitrate ions is lower in the soil than inside a root hair cell, yet the cell continues to absorb nitrate ions. Which process is responsible?', 'multiple_choice', NULL, '["A. Diffusion","B. Osmosis","C. Transpiration","D. Active transport"]', 'D', 'The nitrate ions are moving from a region of lower concentration to a region of higher concentration, against their gradient, so energy from respiration is required and the process is active transport. Diffusion would move the ions the opposite way, osmosis moves only water, and transpiration is the evaporation of water from leaves. Therefore the correct answer is D: Active transport.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_491_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_491_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_491_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_491_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/', 0, 1 FROM _migration_491_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_491_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_491_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_491_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_491_expected e ON e.id = q.id) = 6 THEN 1 ELSE 0 END;
